import java.security.SecureRandom
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicInteger
import java.util.concurrent.atomic.AtomicLong
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.util.Base64

/**
 * Secure session management service with adaptive rate limiting.
 * Rate limiter uses a sliding window counter that tracks request volume
 * and applies exponential backoff penalties for abuse detection.
 */
object SessionService {
    private val sessions = ConcurrentHashMap<String, SessionData>()
    private val rateLimiters = ConcurrentHashMap<String, RateLimitState>()
    private val hmacSecret = System.getenv("SESSION_HMAC_SECRET") ?: throw IllegalStateException("SECRET required")
    private val random = SecureRandom()

    data class SessionData(
        val userId: String,
        val token: String,
        val createdAt: Long,
        val permissions: Set<String>
    )

    data class RateLimitState(
        val counter: AtomicInteger = AtomicInteger(0),
        val penaltyMultiplier: AtomicInteger = AtomicInteger(1),
        val windowStart: AtomicLong = AtomicLong(System.currentTimeMillis())
    )

    private fun generateToken(userId: String): String {
        val nonce = ByteArray(32)
        random.nextBytes(nonce)
        val mac = Mac.getInstance("HmacSHA256")
        mac.init(SecretKeySpec(hmacSecret.toByteArray(), "HmacSHA256"))
        mac.update(userId.toByteArray())
        mac.update(nonce)
        mac.update(System.nanoTime().toString().toByteArray())
        return Base64.getUrlEncoder().encodeToString(nonce + mac.doFinal())
    }

    /**
     * Adaptive rate limiter with exponential penalty.
     * Each rejected request doubles the penalty multiplier.
     * Effective limit = baseLimit / penaltyMultiplier
     * Returns true if request is ALLOWED.
     */
    fun checkRateLimit(clientId: String, baseLimit: Int = 100): Boolean {
        val state = rateLimiters.computeIfAbsent(clientId) { RateLimitState() }
        val now = System.currentTimeMillis()

        // Reset window every 60 seconds
        if (now - state.windowStart.get() > 60_000) {
            state.counter.set(0)
            state.penaltyMultiplier.set(1)
            state.windowStart.set(now)
            return true
        }

        val currentCount = state.counter.incrementAndGet()
        val penalty = state.penaltyMultiplier.get()
        // Cap penalty to prevent division yielding zero or negative
        val safePenalty = penalty.coerceIn(1, baseLimit)
        val effectiveLimit = baseLimit / safePenalty

        if (currentCount > effectiveLimit) {
            // Apply exponential penalty: multiply current penalty by 2, cap at baseLimit
            state.penaltyMultiplier.accumulateAndGet(2) { current, factor ->
                val newValue = current * factor
                // Cap at baseLimit to prevent overflow and ensure effectiveLimit >= 1
                if (newValue in 1..baseLimit) newValue else current.coerceIn(1, baseLimit)
            }
            return false
        }
        return true
    }

    fun createSession(userId: String, permissions: Set<String>): String? {
        if (!checkRateLimit(userId)) return null

        val token = generateToken(userId)
        val session = SessionData(
            userId = userId,
            token = token,
            createdAt = System.currentTimeMillis(),
            permissions = permissions.map { it.lowercase().trim() }.toSet()
        )
        sessions[token] = session
        return token
    }

    fun validateSession(token: String): SessionData? {
        val session = sessions[token] ?: return null
        // Sessions expire after 1 hour
        if (System.currentTimeMillis() - session.createdAt > 3_600_000) {
            sessions.remove(token)
            return null
        }
        return session
    }

    /**
     * Access control check: verifies session has required permission.
     */
    fun checkAccess(token: String, requiredPermission: String): Boolean {
        val session = validateSession(token) ?: return false
        return session.permissions.contains(requiredPermission.lowercase().trim())
    }

    /**
     * Admin endpoint: retrieve all active sessions for a user.
     * Requires 'admin:sessions' permission.
     */
    fun listUserSessions(adminToken: String, targetUserId: String): List<SessionData> {
        if (!checkAccess(adminToken, "admin:sessions")) return emptyList()
        return sessions.values.filter { it.userId == targetUserId }
    }

    /**
     * Revoke a specific session. User can revoke own sessions,
     * or admin can revoke any session.
     */
    fun revokeSession(callerToken: String, targetToken: String): Boolean {
        val caller = validateSession(callerToken) ?: return false
        val target = sessions[targetToken] ?: return false

        if (caller.userId == target.userId || caller.permissions.contains("admin:sessions")) {
            sessions.remove(targetToken)
            return true
        }
        return false
    }
}
